mapper.select:
SELECT rb.id AS id, rb.members_username AS members_username, rb.title AS title, rb.detail AS detail, rb.address AS address, rb.postcode AS postcode, rb.price AS price, rb.house_size AS house_size, rb.price_per AS price_per, rb.rent_start AS rent_start, rb.rent_until AS rent_until, rb.hashtags AS hashtags, rb.views AS views, rb.created_at AS created_at, rb.updated_at AS updated_at, rbi.url AS thumbnail_url, m.profile_image_path AS profileImagePath, m.nickname AS nickname FROM roomboards rb LEFT JOIN roomboards_images rbi ON rb.id = rbi.roomboards_id AND rbi.image_order = 0 LEFT JOIN members m ON rb.members_username = m.username
rb.id < #{cursorId}
ORDER BY rb.id DESC LIMIT #{pageSize};

SELECT id, url, image_order, roomboards_id
FROM roomboards_images
WHERE roomboards_id = #{roomboardsId}
ORDER BY image_order ASC;

SELECT rb.id AS id, rb.members_username AS members_username, rb.title AS title, rb.detail AS detail, rb.address AS address, rb.postcode AS postcode, rb.price AS price, rb.house_size AS house_size, rb.price_per AS price_per, rb.rent_start AS rent_start, rb.rent_until AS rent_until, rb.hashtags AS hashtags, rb.views AS views, rb.created_at AS created_at, rb.updated_at AS updated_at, rbi.url AS thumbnail_url, m.profile_image_path AS profileImagePath, m.nickname AS nickname FROM roomboards rb LEFT JOIN roomboards_images rbi ON rb.id = rbi.roomboards_id AND rbi.image_order = 0 LEFT JOIN members m ON rb.members_username = m.username WHERE
JSON_CONTAINS(rb.hashtags, CONCAT('"', #{tag}, '"'), '$')
ORDER BY rb.id DESC;

SELECT rb.id AS id, rb.members_username AS members_username, rb.title AS title, rb.detail AS detail, rb.address AS address, rb.postcode AS postcode, rb.price AS price, rb.house_size AS house_size, rb.price_per AS price_per, rb.rent_start AS rent_start, rb.rent_until AS rent_until, rb.hashtags AS hashtags, rb.views AS views, rb.created_at AS created_at, rb.updated_at AS updated_at, rbi.url AS thumbnail_url, m.profile_image_path AS profile_image_path, m.nickname AS nickname FROM roomboards rb LEFT JOIN roomboards_images rbi ON rb.id = rbi.roomboards_id AND rbi.image_order = 0 LEFT JOIN members m ON rb.members_username = m.username WHERE 1=1
AND JSON_CONTAINS(rb.hashtags, CONCAT('\"', #{hashtags[0]}, '\"'), '$')
AND rb.rent_start >= #{rentFrom}
AND (rb.rent_until IS NULL OR rb.rent_until <= #{rentTo})
AND rb.address LIKE CONCAT('%', #{address}, '%')
AND rb.price >= #{priceMin}
AND rb.price <= #{priceMax}
AND rb.house_size >= #{sizeMin}
AND rb.house_size <= #{sizeMax}
ORDER BY rb.created_at DESC;
